// tests/vitest/agentic-eval-overview.test.js
// Guard for the overview figure and the root README block it feeds: tools/runs/agentic-benchmark-overview.svg and the block
// between <!-- agentic-benchmark:start/end --> in README.md, both generated by `readme-evidence.mjs --overview` from the campaign
// registry tools/runs/agentic-benchmark-campaigns.json, plus the same figure at the top of docs/agentic-benchmark.md. Every value
// is recomputed here from the committed summaries and cost estimates, independently of the generator. No network calls.

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { readFileSync, writeFileSync, mkdirSync, mkdtempSync, rmSync, cpSync, existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import {
  loadCampaignRegistry, computeOverviewLayout, renderOverviewSvg, buildOverviewAlt, renderOverviewBlock, renderOverviewDocBlock,
  checkOverview, writeOverview, OVERVIEW_REGISTRY_PATH, OVERVIEW_SVG_PATH,
  loadSummary, loadCostEstimate, renderScorecardSvg, renderMetricsGridSvg, checkEvidenceCharts,
  missingSessionsOf, missingSessionsClause,
  README_BLOCK_OWNER, ownsReadmeBlock, COLOR_WITH, COLOR_WITHOUT, COLOR_TEXT, COLOR_SECONDARY, FONT_STACK,
} from '../../tools/agentic-eval/readme-evidence.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(__dirname, '..', '..');
const RUNS = join(REPO_ROOT, 'tools', 'runs');
const README_PATH = join(REPO_ROOT, 'README.md');
const DOC_PATH = join(REPO_ROOT, 'docs', 'agentic-benchmark.md');
const SCRIPT = join(REPO_ROOT, 'tools', 'agentic-eval', 'readme-evidence.mjs');
const E2 = 'evidence2-agentic-benchmark-2026-09-30';
const E3 = 'evidence3-agentic-benchmark-2026-10-02';
const LABELS = ['1 module · run its tests, check a coverage budget', '11 modules · find the 6 failing tests'];
const NOTES = [undefined, 'An earlier attempt failed on infrastructure and is not analyzed.'];
const RUNTIMES = ['claude-code', 'codex-cli'];
const ARMS = ['product', 'free'];
const AGENT_NAME = { 'claude-code': 'Claude Code', 'codex-cli': 'Codex CLI' };

// The design's constants, typed out here rather than imported, so that a change in the generator fails this file instead of following it.
const W = 880;
const PAD = 28;
const BAR_MAX = 118;
const COLUMN_X = { calls: 196, cost: 376, wall: 556, kf: 744 };
const NEXT_COLUMN_X = { calls: COLUMN_X.cost, cost: COLUMN_X.wall, wall: COLUMN_X.kf };
const COLUMN_KEYS = ['calls', 'cost', 'wall'];

const crlf = (s) => s.replace(/\r\n/g, '\n');
const toCrlf = (s) => s.replace(/\r\n/g, '\n').replace(/\n/g, '\r\n');
const loadJson = (p) => JSON.parse(readFileSync(p, 'utf8'));
const median = (values) => {
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
};

// One session's estimated cost from the price table and the tokens: the cache write at the mean of the 5-minute and 1-hour rates, and
// uncached input at the mean of the plain input rate and, where the provider cannot tell a cache write from plain input, the dearer cache write rate.
function sessionCost(costEstimate, cell) {
  const entry = costEstimate.runtimes[cell.runtime_id];
  const tokens = entry.cells.find((c) => c.arm === cell.arm && c.order_index === cell.round_index).tokens;
  const p = entry.per_million_tokens;
  const dearInput = entry.uncached_input_may_be_cache_writes === true ? Math.max(p.cache_write_5m, p.cache_write_1h) : p.input;
  return ((tokens.cache_creation * (p.cache_write_5m + p.cache_write_1h)) / 2 + tokens.cache_read * p.cache_read + tokens.output * p.output + (tokens.input * (p.input + dearInput)) / 2) / 1e6;
}

/** What the figure and the block must say for one campaign directory, recomputed here from its summary and cost estimate. */
function expectedFor(dir) {
  const summary = loadJson(join(RUNS, dir, 'campaign-summary.json'));
  const costEstimate = loadJson(join(RUNS, dir, 'cost-estimate.json'));
  const groups = RUNTIMES.map((runtimeId) => ARMS.map((arm) => {
    const cells = summary.cells.filter((c) => c.runtime_id === runtimeId && c.arm === arm && c.status !== 'missing');
    const declared = summary.by_runtime_arm.find((g) => g.runtime_id === runtimeId && g.arm === arm).declared;
    return {
      runtimeId, arm, declared, counted: cells.length,
      calls: median(cells.map((c) => c.tool_calls_total)),
      cost: median(cells.map((c) => sessionCost(costEstimate, c))),
      wall: median(cells.map((c) => c.duration_ms)) / 60000,
      kf: `${cells.filter((c) => c.key_facts_match === true).length}/${cells.length}`,
    };
  }));
  const versions = {
    kmpTest: summary.provenance.kmp_test_cli_version.values[0],
    runtimes: Object.fromEntries(RUNTIMES.map((r) => [r, summary.provenance.runtime_cli_version[r].values[0]])),
    models: Object.fromEntries(RUNTIMES.map((r) => [r, summary.provenance.model_resolved[r].values[0]])),
  };
  return { dir, groups, versions };
}

const fmtCalls = (v) => (Number.isInteger(v) ? String(v) : v.toFixed(1));
const fmtCost = (v) => `$${v.toFixed(3)}`;
const fmtWall = (v) => `${v.toFixed(1)} min`;
const FORMAT = { calls: fmtCalls, cost: fmtCost, wall: fmtWall };

// A minimal runs root holding Evidence2's three files, for the registry's failure reasons.
function scratchRuns() {
  const root = mkdtempSync(join(tmpdir(), 'kmp-overview-'));
  const dir = join(root, E2);
  mkdirSync(dir, { recursive: true });
  for (const name of ['campaign-summary.json', 'cost-estimate.json', 'README.md']) cpSync(join(RUNS, E2, name), join(dir, name));
  const registryPath = join(root, 'agentic-benchmark-campaigns.json');
  const writeRegistry = (registry) => writeFileSync(registryPath, typeof registry === 'string' ? registry : JSON.stringify(registry));
  writeRegistry({ schema: 1, campaigns: [{ dir: E2, label: LABELS[0] }] });
  return { root, dir, registryPath, writeRegistry, cleanup: () => rmSync(root, { recursive: true, force: true }) };
}

describe('the campaign registry', () => {
  it('the committed registry lists Evidence2 and Evidence3, in that order, with their labels, and not Evidence1', () => {
    const registry = loadJson(OVERVIEW_REGISTRY_PATH);
    expect(registry.schema).toBe(1);
    expect(registry.campaigns).toEqual([{ dir: E2, label: LABELS[0] }, { dir: E3, label: LABELS[1], note: NOTES[1] }]);
    const campaigns = loadCampaignRegistry();
    expect(campaigns.map((c) => [c.dir, c.label, c.evidenceN, c.note])).toEqual([[E2, LABELS[0], 2, undefined], [E3, LABELS[1], 3, NOTES[1]]]);
    expect(Object.keys(campaigns[0])).not.toContain('note');
    for (const c of campaigns) {
      expect(c.summary.by_runtime_arm).toHaveLength(4);
      expect(c.costEstimate.schema).toBe(2);
    }
  });

  describe('fails closed, one reason per check', () => {
    let scratch;
    beforeAll(() => { scratch = scratchRuns(); });
    afterAll(() => scratch.cleanup());
    const load = () => loadCampaignRegistry(scratch.registryPath, scratch.root);
    const good = () => ({ schema: 1, campaigns: [{ dir: E2, label: LABELS[0] }] });

    it('accepts a valid registry (the scratch one)', () => {
      scratch.writeRegistry(good());
      expect(load().map((c) => c.dir)).toEqual([E2]);
    });

    it('rejects a registry that is not JSON', () => {
      scratch.writeRegistry('{ not json');
      expect(load).toThrow(/not valid JSON/);
    });

    it('rejects a schema other than 1', () => {
      scratch.writeRegistry({ ...good(), schema: 2 });
      expect(load).toThrow(/schema must be 1/);
    });

    it('rejects a registry without campaigns, and one whose campaigns is not an array', () => {
      scratch.writeRegistry({ schema: 1, campaigns: [] });
      expect(load).toThrow(/at least one campaign/);
      scratch.writeRegistry({ schema: 1, campaigns: 'x' });
      expect(load).toThrow(/at least one campaign/);
    });

    it('rejects a directory listed twice', () => {
      scratch.writeRegistry({ schema: 1, campaigns: [{ dir: E2, label: 'a' }, { dir: E2, label: 'b' }] });
      expect(load).toThrow(new RegExp(`duplicate dir ${E2}`));
    });

    it('rejects a directory name that is not evidence<N>-agentic-benchmark-<date>, because the figure names the evidence from it', () => {
      scratch.writeRegistry({ schema: 1, campaigns: [{ dir: 'some-run', label: 'a' }] });
      expect(load).toThrow(/some-run: the directory name must be evidence<N>-agentic-benchmark-<yyyy-mm-dd>/);
    });

    it('rejects a directory that does not exist', () => {
      scratch.writeRegistry({ schema: 1, campaigns: [{ dir: 'evidence9-agentic-benchmark-2027-01-01', label: 'a' }] });
      expect(load).toThrow(/evidence9-agentic-benchmark-2027-01-01: directory not found/);
    });

    it.each(['campaign-summary.json', 'cost-estimate.json', 'README.md'])('rejects a directory without %s', (name) => {
      scratch.writeRegistry(good());
      const file = join(scratch.dir, name);
      const bytes = readFileSync(file);
      rmSync(file);
      try {
        expect(load).toThrow(new RegExp(`${E2}: ${name.replace('.', '\\.')} not found`));
      } finally {
        writeFileSync(file, bytes);
      }
    });

    it('rejects an empty or missing label', () => {
      scratch.writeRegistry({ schema: 1, campaigns: [{ dir: E2, label: '' }] });
      expect(load).toThrow(new RegExp(`${E2}: label must be a non-empty string`));
      scratch.writeRegistry({ schema: 1, campaigns: [{ dir: E2 }] });
      expect(load).toThrow(new RegExp(`${E2}: label must be a non-empty string`));
    });

    it('accepts a missing note and a non-empty one, and passes the note through unchanged', () => {
      scratch.writeRegistry(good());
      expect(Object.keys(load()[0])).not.toContain('note');
      scratch.writeRegistry({ schema: 1, campaigns: [{ dir: E2, label: LABELS[0], note: 'A note.' }] });
      expect(load()[0].note).toBe('A note.');
    });

    it.each([['a number', 5], ['an empty string', ''], ['only spaces', '   '], ['null', null], ['an object', { text: 'x' }]])('rejects a note that is %s', (_, note) => {
      scratch.writeRegistry({ schema: 1, campaigns: [{ dir: E2, label: LABELS[0], note }] });
      expect(load).toThrow(new RegExp(`${E2}: note must be a non-empty string when present`));
    });

    it('rejects a summary that fails validateSummary', () => {
      scratch.writeRegistry(good());
      const file = join(scratch.dir, 'campaign-summary.json');
      const original = readFileSync(file, 'utf8');
      const broken = JSON.parse(original);
      broken.summary_status = 'partial';
      writeFileSync(file, JSON.stringify(broken));
      try {
        expect(load).toThrow(new RegExp(`${E2}: campaign-summary.json failed validation`));
      } finally {
        writeFileSync(file, original);
      }
    });

    it('rejects a summary and a cost estimate that do not pair', () => {
      scratch.writeRegistry(good());
      const file = join(scratch.dir, 'cost-estimate.json');
      const original = readFileSync(file, 'utf8');
      const broken = JSON.parse(original);
      const before = broken.runtimes['claude-code'].cells.length;
      broken.runtimes['claude-code'].cells = broken.runtimes['claude-code'].cells.filter((c) => !(c.arm === 'free' && c.order_index === 1)); // Evidence2's Claude Code free arm ran rounds 1, 2, 4 and 7
      expect(broken.runtimes['claude-code'].cells).toHaveLength(before - 1);
      writeFileSync(file, JSON.stringify(broken));
      try {
        expect(load).toThrow(new RegExp(`${E2}: campaign-summary.json / cost-estimate.json mismatch`));
      } finally {
        writeFileSync(file, original);
      }
    });
  });
});

describe('the overview figure', () => {
  let campaigns, layout, svg, expected, committedSvg;
  beforeAll(() => {
    campaigns = loadCampaignRegistry();
    layout = computeOverviewLayout(campaigns);
    svg = renderOverviewSvg(campaigns);
    expected = campaigns.map((c) => expectedFor(c.dir));
    committedSvg = readFileSync(OVERVIEW_SVG_PATH, 'utf8');
  });

  const textsOf = (role) => layout.items.filter((i) => i.kind === 'text' && i.role === role);
  // The expected values in drawing order: per campaign, per agent, with kmp-test then without.
  const flat = () => expected.flatMap((e) => e.groups.flat());

  it('is the generator output byte for byte (CRLF-normalized), at tools/runs/agentic-benchmark-overview.svg', () => {
    expect(OVERVIEW_SVG_PATH).toBe(join(RUNS, 'agentic-benchmark-overview.svg'));
    expect(crlf(committedSvg)).toBe(crlf(svg));
  });

  it('uses only svg, title, desc, rect and text elements, with no tspan, line, circle, path or other decoration', () => {
    const tags = new Set([...svg.matchAll(/<([a-zA-Z][\w:-]*)/g)].map((m) => m[1]));
    expect([...tags].sort()).toEqual(['desc', 'rect', 'svg', 'text', 'title']);
    expect(svg).not.toMatch(/<(tspan|line|circle|path|polyline|polygon|ellipse|style|script|foreignObject|image|use|filter)\b/);
    expect(svg).not.toContain('<!--');
  });

  it('is an accessible image with the repository\'s card and font: role="img", a title, a desc, width 880', () => {
    expect(svg).toMatch(/^<svg viewBox="0 0 880 \d+" width="880" height="\d+"/);
    expect(svg).toMatch(/^<svg [^>]*role="img"/);
    expect(svg).toContain('<title>Agent sessions with and without kmp-test</title>');
    expect(svg).toMatch(/<desc>[^<]+<\/desc>/);
    expect(svg).toContain(`font-family="${FONT_STACK}"`);
    const grid = readFileSync(join(RUNS, E3, 'metrics-grid.svg'), 'utf8');
    const card = (s) => s.match(/<rect x="1" y="1"[^>]*rx="12"[^>]*\/>/)[0].replace(/ width="\d+" height="\d+"/, '');
    expect(card(svg)).toBe(card(grid));
    expect(svg.match(/<svg [^>]*font-family="([^"]*)"/)[1]).toBe(grid.match(/<svg [^>]*font-family="([^"]*)"/)[1]);
    expect(layout.width).toBe(W);
  });

  it('has the header the design says: title, a subtitle that says each scenario compares only its own two arms, and the two arm swatches', () => {
    expect(textsOf('overviewTitle').map((t) => [t.text, t.fontSize, t.fontWeight])).toEqual([['Agent sessions with and without kmp-test', 20, 600]]);
    const subtitle = textsOf('overviewSubtitle').map((t) => t.text).join(' ');
    expect(subtitle).toBe('Median per session. Each scenario is its own pre-registered campaign on NowInAndroid and compares only its own two arms; bars share one scale per column.');
    expect(textsOf('overviewLegend').map((t) => [t.text, t.fill])).toEqual([['with kmp-test', COLOR_SECONDARY], ['without', COLOR_SECONDARY]]);
    const swatches = layout.items.filter((i) => i.kind === 'legendSwatch');
    expect(swatches.map((s) => s.fill)).toEqual([COLOR_WITH, COLOR_WITHOUT]);
    expect(textsOf('overviewColumnHead').map((t) => [t.text, t.x])).toEqual([
      ['Tool calls', COLUMN_X.calls], ['Est. API cost', COLUMN_X.cost], ['Wall-clock', COLUMN_X.wall], ['Key facts correct', COLUMN_X.kf],
    ]);
  });

  it('draws the scenarios in registry order, each with its title and, on its own line under it, its meta', () => {
    const titles = textsOf('overviewScenarioTitle');
    const metas = textsOf('overviewScenarioMeta');
    expect(titles.map((t) => t.text)).toEqual(LABELS);
    expect(metas.map((t) => t.text)).toEqual(['Evidence2 · 4 + 4 sessions per agent', 'Evidence3 · 8 + 7 sessions counted per agent']);
    titles.forEach((title, i) => {
      expect([title.fontSize, title.fontWeight, title.fill]).toEqual([14, 600, COLOR_TEXT]);
      expect([metas[i].fontSize, metas[i].fontWeight, metas[i].fill]).toEqual([12, 400, COLOR_SECONDARY]);
      expect(metas[i].x).toBe(title.x);
      expect(metas[i].y - title.y).toBeGreaterThanOrEqual(14); // its own line, not a run-on of the title
    });
  });

  it('draws Claude Code first, then Codex CLI, in each scenario, each with its resolved model under it', () => {
    expect(textsOf('overviewAgent').map((t) => [t.text, t.fontSize, t.fontWeight])).toEqual(
      [['Claude Code', 13, 500], ['Codex CLI', 13, 500], ['Claude Code', 13, 500], ['Codex CLI', 13, 500]],
    );
    const models = textsOf('overviewModel');
    expect(models.map((t) => t.text)).toEqual(expected.flatMap((e) => RUNTIMES.map((r) => e.versions.models[r])));
    expect(models.map((t) => [t.fontSize, t.fill])).toEqual(models.map(() => [11.5, COLOR_SECONDARY]));
    textsOf('overviewAgent').forEach((agent, i) => expect(models[i].y).toBeGreaterThan(agent.y));
  });

  it.each(COLUMN_KEYS)('prints, in the %s column, every value recomputed from the committed data, at the end of its bar plus a gap of 6', (column) => {
    const values = layout.items.filter((i) => i.kind === 'text' && i.role === 'overviewValue' && i.column === column);
    const bars = layout.items.filter((i) => i.kind === 'bar' && i.column === column);
    expect(values.map((v) => v.text)).toEqual(flat().map((g) => FORMAT[column](g[column])));
    expect(bars).toHaveLength(values.length);
    values.forEach((v, i) => {
      expect(v.x).toBeCloseTo(bars[i].x + bars[i].w + 6, 6);
      expect(v.fontSize).toBe(12);
    });
  });

  it.each(COLUMN_KEYS)('draws every bar of the %s column as value / the column\'s largest value x 118, one scale for every scenario, agent and arm', (column) => {
    const bars = layout.items.filter((i) => i.kind === 'bar' && i.column === column);
    const groups = flat();
    const columnMax = Math.max(...groups.map((g) => g[column]));
    expect(bars).toHaveLength(groups.length);
    bars.forEach((bar, i) => {
      expect(Math.abs(bar.w - (groups[i][column] / columnMax) * BAR_MAX), `${column} bar ${i}`).toBeLessThan(0.1);
      expect(bar.x).toBe(COLUMN_X[column]);
    });
    expect(Math.max(...bars.map((b) => b.w))).toBeCloseTo(BAR_MAX, 6);
  });

  it('draws with kmp-test above without in every row, with the arm colors on the bars and on the key facts', () => {
    for (const column of COLUMN_KEYS) {
      const bars = layout.items.filter((i) => i.kind === 'bar' && i.column === column);
      bars.forEach((bar, i) => {
        expect(bar.fill, `${column} bar ${i}`).toBe(i % 2 === 0 ? COLOR_WITH : COLOR_WITHOUT);
        if (i % 2 === 1) expect(bar.y).toBeGreaterThan(bars[i - 1].y);
      });
    }
    const keyFacts = textsOf('overviewKeyFacts');
    expect(keyFacts.map((t) => t.text)).toEqual(flat().map((g) => g.kf));
    keyFacts.forEach((t, i) => {
      expect([t.x, t.fontSize, t.fontWeight, t.fill]).toEqual([COLUMN_X.kf, 12, 600, i % 2 === 0 ? COLOR_WITH : COLOR_WITHOUT]);
    });
    // The key facts of a lane are on the line of that lane's bars.
    const callBars = layout.items.filter((i) => i.kind === 'bar' && i.column === 'calls');
    keyFacts.forEach((t, i) => expect(Math.abs(t.y - (callBars[i].y + 11 - 1.5))).toBeLessThan(0.5));
  });

  it('has no overlapping text, no value label that crosses into the next column, and everything inside the card', () => {
    const textBox = (i) => {
      const width = i.text.length * i.fontSize * 0.6;
      const x0 = i.anchor === 'end' ? i.x - width : i.anchor === 'middle' ? i.x - width / 2 : i.x;
      return { x0, x1: x0 + width, y0: i.y - i.fontSize * 0.8, y1: i.y + i.fontSize * 0.25, label: i.text, item: i };
    };
    const markBox = (i) => ({ x0: i.x, x1: i.x + i.w, y0: i.y, y1: i.y + i.h });
    const overlap = (a, b) => a.x0 < b.x1 && b.x0 < a.x1 && a.y0 < b.y1 && b.y0 < a.y1;
    const texts = layout.items.filter((i) => i.kind === 'text').map(textBox);
    const marks = layout.items.filter((i) => i.kind === 'bar' || i.kind === 'legendSwatch').map(markBox);
    for (let i = 0; i < texts.length; i++) {
      for (let j = i + 1; j < texts.length; j++) expect(overlap(texts[i], texts[j]), `"${texts[i].label}" overlaps "${texts[j].label}"`).toBe(false);
      for (const m of marks) expect(overlap(texts[i], m), `"${texts[i].label}" overlaps a mark`).toBe(false);
    }
    for (const t of texts.filter((b) => b.item.role === 'overviewValue')) {
      expect(t.x1, `value "${t.label}" crosses into the next column`).toBeLessThanOrEqual(NEXT_COLUMN_X[t.item.column] - 4);
    }
    for (const box of [...texts, ...marks]) {
      expect(box.x0).toBeGreaterThanOrEqual(PAD - 0.5);
      expect(box.x1).toBeLessThanOrEqual(W - 0.5);
      expect(box.y0).toBeGreaterThanOrEqual(0);
      expect(box.y1).toBeLessThanOrEqual(layout.height);
    }
  });

  it('leaves as much room under the last row as the figure has at its sides (28 px), within 2 px', () => {
    const bottoms = layout.items.map((i) => (i.kind === 'text' ? i.y + i.fontSize * 0.25 : i.y + i.h));
    expect(Math.abs(layout.height - Math.max(...bottoms) - PAD)).toBeLessThanOrEqual(2);
  });

  it('has an alt text that names every scenario and agent once, with the values the figure prints', () => {
    const alt = buildOverviewAlt(campaigns);
    const groups = expected.flatMap((e) => RUNTIMES.map((r, ri) => ({ e, r, pair: e.groups[ri] })));
    for (const { e, r, pair } of groups) {
      const clause = `${AGENT_NAME[r]}: ${fmtCalls(pair[0].calls)} vs ${fmtCalls(pair[1].calls)} tool calls, ${fmtCost(pair[0].cost)} vs ${fmtCost(pair[1].cost)}, ${fmtWall(pair[0].wall)} vs ${fmtWall(pair[1].wall)}, key facts ${pair[0].kf} vs ${pair[1].kf}`;
      expect(alt, e.dir + r).toContain(clause);
    }
    for (const label of LABELS) expect(alt.split(label).length - 1).toBe(1);
    expect(alt).not.toMatch(/faster|better|baseline|full[ _-]?answer/i);
  });
});

describe('the root README block', () => {
  let campaigns, readme, block;
  beforeAll(() => {
    campaigns = loadCampaignRegistry();
    readme = crlf(readFileSync(README_PATH, 'utf8'));
    const start = readme.indexOf('<!-- agentic-benchmark:start');
    const end = readme.indexOf('<!-- agentic-benchmark:end -->') + '<!-- agentic-benchmark:end -->'.length;
    block = readme.slice(start, end);
  });

  it('is renderOverviewBlock byte for byte (CRLF-normalized), and the Command output size section follows it unchanged', () => {
    expect(block).toBe(crlf(renderOverviewBlock(campaigns)));
    expect(readme).toContain(`${block}\n\n### Command output size: raw Gradle vs \`kmp-test --json\`\n`);
  });

  it('names the registry and --overview as its source in its start comment', () => {
    expect(block.split('\n')[0]).toBe('<!-- agentic-benchmark:start (generated by tools/agentic-eval/readme-evidence.mjs --overview from tools/runs/agentic-benchmark-campaigns.json; edit the generator or the registry, not this block) -->');
  });

  it('is the intro sentence, the figure with its generated alt text, one bullet per scenario and the closing line, in that order', () => {
    const lines = block.split('\n');
    expect(lines[1]).toBe('### Agent sessions with and without kmp-test');
    expect(lines[3]).toBe('kmp-test hands an agent the test and coverage verdict as one JSON envelope instead of Gradle logs and report files.');
    expect(lines[5]).toBe(`![${buildOverviewAlt(campaigns)}](tools/runs/agentic-benchmark-overview.svg)`);
    const bullets = lines.filter((l) => l.startsWith('- '));
    expect(bullets).toHaveLength(campaigns.length);
    expect(lines[lines.length - 2]).toBe('Each scenario is a separate pre-registered campaign and compares only its own two arms. Method, per-scenario charts, every session and limitations: [docs/agentic-benchmark.md](docs/agentic-benchmark.md).');
    expect(lines[lines.length - 1]).toBe('<!-- agentic-benchmark:end -->');
  });

  it('has, for each scenario, a bullet in the specified form with every number and version recomputed from the committed data', () => {
    const bullets = block.split('\n').filter((l) => l.startsWith('- '));
    const countsOf = (e, same) => (e.groups.every((pair) => pair.every((g) => g.counted === g.declared)) ? `${same[0]} + ${same[1]} sessions per agent` : `${same[0]} + ${same[1]} sessions counted per agent`);
    [E2, E3].forEach((dir, i) => {
      const e = expectedFor(dir);
      const [claude, codex] = e.groups;
      const counts = countsOf(e, [claude[0].counted, claude[1].counted]);
      const evidence = `Evidence${i + 2}`;
      const missing = e.groups.flat().reduce((sum, g) => sum + g.declared - g.counted, 0);
      const missingClause = missing > 0 ? ` ${missing} session${missing === 1 ? '' : 's'} missing data (not counted, not replaced).` : '';
      const noteClause = NOTES[i] ? ` ${NOTES[i]}` : '';
      const line = `- **${LABELS[i]}** (${evidence}, ${counts}): median tool calls ${fmtCalls(claude[0].calls)} vs ${fmtCalls(claude[1].calls)} (Claude Code) and ${fmtCalls(codex[0].calls)} vs ${fmtCalls(codex[1].calls)} (Codex CLI); median estimated cost ${fmtCost(claude[0].cost)} vs ${fmtCost(claude[1].cost)} and ${fmtCost(codex[0].cost)} vs ${fmtCost(codex[1].cost)}; key facts ${claude[0].kf} vs ${claude[1].kf} and ${codex[0].kf} vs ${codex[1].kf}. kmp-test ${e.versions.kmpTest} · Claude Code ${e.versions.runtimes['claude-code']} · Codex CLI ${e.versions.runtimes['codex-cli']}.${missingClause}${noteClause} [Record](tools/runs/${dir}/README.md)`;
      expect(bullets[i]).toBe(line);
    });
  });

  it('Evidence3\'s bullet discloses its 2 missing sessions and the unanalyzed earlier attempt after its versions, before the record link; Evidence2\'s says neither', () => {
    const [bullet2, bullet3] = block.split('\n').filter((l) => l.startsWith('- '));
    expect(bullet3).toMatch(/Codex CLI 0\.154\.0\. 2 sessions missing data \(not counted, not replaced\)\. An earlier attempt failed on infrastructure and is not analyzed\. \[Record\]\(tools\/runs\/evidence3-agentic-benchmark-2026-10-02\/README\.md\)$/);
    expect(bullet2).not.toMatch(/missing data|earlier attempt|not analyzed/);
    expect(bullet2).toMatch(/Codex CLI 0\.154\.0\. \[Record\]\(tools\/runs\/evidence2-agentic-benchmark-2026-09-30\/README\.md\)$/);
  });

  it('links and shows only files that exist on disk', () => {
    const targets = [...block.matchAll(/\]\(([^)#\s]+)(?:#[^)]*)?\)/g)].map((m) => m[1]);
    expect(targets).toEqual([
      'tools/runs/agentic-benchmark-overview.svg', `tools/runs/${E2}/README.md`, `tools/runs/${E3}/README.md`, 'docs/agentic-benchmark.md',
    ]);
    for (const target of targets) expect(existsSync(join(REPO_ROOT, target)), target).toBe(true);
  });

  it('never says faster, better or baseline, never states a ratio, a cross-scenario comparison or a full-answer number (task B3), and states the one-campaign rule', () => {
    expect(block).not.toMatch(/faster|slower|better|worse|cheaper|baseline|full[ _-]?answer/i);
    expect(block).not.toMatch(/\d+(\.\d+)?\s*(x|×|times)\b/i);
    expect(block).not.toMatch(/all agents|across scenarios|in both scenarios|improv|saves?\b|reduction|%/i);
    expect(block).not.toMatch(/\{\{/);
    expect(block).not.toMatch(/:core:|:feature:|BookmarksViewModelTest|CompositeUserNewsResourceRepositoryTest|GetFollowableTopicsUseCaseTest/);
    expect(block).toContain('compares only its own two arms');
    expect(block).not.toMatch(/\bnew\b|release|what's new/i);
  });
});

describe('the detailed document', () => {
  let campaigns, doc;
  beforeAll(() => {
    campaigns = loadCampaignRegistry();
    doc = crlf(readFileSync(DOC_PATH, 'utf8'));
  });

  it('shows the overview figure right after "What is measured", in a generated block, with the same alt text as the README', () => {
    const block = renderOverviewDocBlock(campaigns);
    expect(doc).toContain(block);
    expect(block).toContain(`![${buildOverviewAlt(campaigns)}](../tools/runs/agentic-benchmark-overview.svg)`);
    const measured = doc.indexOf('## What is measured');
    const evidence2 = doc.indexOf('## Evidence2 (');
    expect(measured).toBeGreaterThan(-1);
    const between = doc.slice(measured, evidence2);
    expect(between.trimEnd().endsWith(block)).toBe(true);
    expect(doc.slice(doc.indexOf(block) + block.length).startsWith('\n\n## Evidence2 (')).toBe(true);
  });
});

describe('--overview', () => {
  let campaigns, scratch;
  const seed = () => {
    const dir = mkdtempSync(join(tmpdir(), 'kmp-overview-out-'));
    const paths = { svgPath: join(dir, 'overview.svg'), readmePath: join(dir, 'README.md'), docPath: join(dir, 'doc.md') };
    writeFileSync(paths.readmePath, 'intro\n\n<!-- agentic-benchmark:start (old) -->\nold block\n<!-- agentic-benchmark:end -->\n\n### Command output size\n');
    writeFileSync(paths.docPath, '# doc\n\n## What is measured\n\ntext\n\n<!-- agentic-benchmark-overview:start (old) -->\nold\n<!-- agentic-benchmark-overview:end -->\n\n## Evidence2 (x)\n');
    return { dir, paths, cleanup: () => rmSync(dir, { recursive: true, force: true }) };
  };
  beforeAll(() => { campaigns = loadCampaignRegistry(); scratch = seed(); });
  afterAll(() => scratch.cleanup());

  it('writes the figure, the README block and the document block, and leaves the rest of both files alone', () => {
    writeOverview(campaigns, scratch.paths);
    expect(readFileSync(scratch.paths.svgPath, 'utf8')).toBe(renderOverviewSvg(campaigns));
    const readme = readFileSync(scratch.paths.readmePath, 'utf8');
    expect(readme).toBe(`intro\n\n${renderOverviewBlock(campaigns)}\n\n### Command output size\n`);
    const doc = readFileSync(scratch.paths.docPath, 'utf8');
    expect(doc).toBe(`# doc\n\n## What is measured\n\ntext\n\n${renderOverviewDocBlock(campaigns)}\n\n## Evidence2 (x)\n`);
  });

  it('checks: nothing is stale after a write, a CRLF copy of every file is not stale, and each kind of drift is named', () => {
    writeOverview(campaigns, scratch.paths);
    expect(checkOverview(campaigns, scratch.paths)).toEqual([]);
    const original = Object.fromEntries(Object.entries(scratch.paths).map(([k, p]) => [k, readFileSync(p, 'utf8')]));
    try {
      for (const [k, p] of Object.entries(scratch.paths)) writeFileSync(p, toCrlf(original[k]));
      expect(checkOverview(campaigns, scratch.paths)).toEqual([]);
      writeFileSync(scratch.paths.svgPath, original.svgPath.replace('Tool calls', 'Tool call'));
      expect(checkOverview(campaigns, scratch.paths)).toEqual([scratch.paths.svgPath]);
      writeFileSync(scratch.paths.svgPath, original.svgPath);
      writeFileSync(scratch.paths.readmePath, original.readmePath.replace('compares only', 'compares'));
      expect(checkOverview(campaigns, scratch.paths)).toEqual([scratch.paths.readmePath]);
      writeFileSync(scratch.paths.readmePath, original.readmePath);
      writeFileSync(scratch.paths.docPath, original.docPath.replace('](../tools/runs/agentic-benchmark-overview.svg)', '](../tools/runs/other.svg)'));
      expect(checkOverview(campaigns, scratch.paths)).toEqual([scratch.paths.docPath]);
      rmSync(scratch.paths.svgPath);
      writeFileSync(scratch.paths.docPath, original.docPath);
      expect(checkOverview(campaigns, scratch.paths)).toEqual([scratch.paths.svgPath]);
    } finally {
      for (const [k, p] of Object.entries(scratch.paths)) writeFileSync(p, original[k]);
    }
  });

  it('refuses a README or a document without its markers instead of appending or guessing', () => {
    const other = seed();
    try {
      writeFileSync(other.paths.readmePath, '# no markers\n');
      expect(() => writeOverview(campaigns, other.paths)).toThrow(/README\.md is missing the agentic-benchmark:start\/end markers/);
      writeFileSync(other.paths.readmePath, 'a\n<!-- agentic-benchmark:start (x) -->\nb\n<!-- agentic-benchmark:end -->\n');
      writeFileSync(other.paths.docPath, '# no markers\n');
      expect(() => writeOverview(campaigns, other.paths)).toThrow(/agentic-benchmark-overview:start\/end markers/);
    } finally {
      other.cleanup();
    }
  });

  it('the committed files are up to date: node readme-evidence.mjs --overview --check exits 0 and names no stale file', () => {
    const result = spawnSync(process.execPath, [SCRIPT, '--overview', '--check'], { encoding: 'utf8' });
    expect(result.status, result.stderr).toBe(0);
    expect(result.stdout).toContain('Overview figure, README block and document block are up to date.');
    expect(checkOverview(campaigns)).toEqual([]);
  });

  it('an evidence checks its own two SVGs with line endings ignored (a Windows autocrlf checkout holds CRLF) and names each drifted or missing one', () => {
    const dir = mkdtempSync(join(tmpdir(), 'kmp-overview-charts-'));
    try {
      const summary = loadSummary(join(RUNS, E3, 'campaign-summary.json'));
      const costEstimate = loadCostEstimate(join(RUNS, E3, 'cost-estimate.json'));
      const paths = { scorecardPath: join(dir, 'scorecard.svg'), metricsGridPath: join(dir, 'metrics-grid.svg') };
      const scorecard = renderScorecardSvg(summary, costEstimate);
      const grid = renderMetricsGridSvg(summary, costEstimate);
      writeFileSync(paths.scorecardPath, scorecard);
      writeFileSync(paths.metricsGridPath, grid);
      expect(checkEvidenceCharts(summary, costEstimate, paths)).toEqual([]);
      writeFileSync(paths.scorecardPath, toCrlf(scorecard));
      writeFileSync(paths.metricsGridPath, toCrlf(grid));
      expect(checkEvidenceCharts(summary, costEstimate, paths)).toEqual([]);
      writeFileSync(paths.scorecardPath, scorecard.replace('<svg', '<svg data-drift="1"'));
      expect(checkEvidenceCharts(summary, costEstimate, paths)).toEqual([paths.scorecardPath]);
      writeFileSync(paths.scorecardPath, scorecard);
      writeFileSync(paths.metricsGridPath, grid.replace('<svg', '<svg data-drift="1"'));
      expect(checkEvidenceCharts(summary, costEstimate, paths)).toEqual([paths.metricsGridPath]);
      rmSync(paths.scorecardPath);
      rmSync(paths.metricsGridPath);
      expect(checkEvidenceCharts(summary, costEstimate, paths)).toEqual([paths.scorecardPath, paths.metricsGridPath]);
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });

  it('each evidence still checks its own two SVGs only: --evidence=2 and --evidence=3 --check exit 0 and never read or write the README block', () => {
    for (const [n, date] of [[2, '2026-09-30'], [3, '2026-10-02']]) {
      const before = readFileSync(README_PATH, 'utf8');
      const result = spawnSync(process.execPath, [SCRIPT, `--evidence=${n}`, `--date=${date}`, '--check'], { encoding: 'utf8' });
      expect(result.status, result.stderr).toBe(0);
      expect(result.stdout).toContain(`Evidence ${n} charts are up to date.`);
      expect(readFileSync(README_PATH, 'utf8')).toBe(before);
    }
  });

  it('no evidence owns the root README block any more: the overview does', () => {
    expect(README_BLOCK_OWNER).toBe('overview');
    for (const n of [1, 2, 3, 4, '1', '2', '3', '4']) expect(ownsReadmeBlock(n), String(n)).toBe(false);
  });
});

describe('the missing-sessions clause of an overview bullet', () => {
  const group = (declared, counted) => ({ declared, ...(counted === undefined ? {} : { counted }) });
  const summaryOf = (...groups) => ({
    by_runtime_arm: RUNTIMES.flatMap((runtime_id) => ARMS.map((arm) => ({ runtime_id, arm, ...groups.shift() }))),
  });

  it('is the sum of declared minus counted over the four groups; a group without a counted value counts all its declared sessions', () => {
    expect(missingSessionsOf(summaryOf(group(8), group(8), group(8), group(8)))).toBe(0);
    expect(missingSessionsOf(summaryOf(group(8, 8), group(8, 7), group(8, 8), group(8, 7)))).toBe(2);
    expect(missingSessionsOf(summaryOf(group(4, 4), group(4, 4), group(4, 3), group(4, 4)))).toBe(1);
    expect(missingSessionsOf(summaryOf(group(8, 6), group(8, 5), group(8, 8), group(8, 8)))).toBe(5);
  });

  it('reads "<n> session(s) missing data (not counted, not replaced)." with the singular for one and nothing for none', () => {
    expect(missingSessionsClause(0)).toBe('');
    expect(missingSessionsClause(1)).toBe('1 session missing data (not counted, not replaced).');
    expect(missingSessionsClause(2)).toBe('2 sessions missing data (not counted, not replaced).');
    expect(missingSessionsClause(5)).toBe('5 sessions missing data (not counted, not replaced).');
  });

  it('agrees with the committed summaries: Evidence2 none, Evidence3 two', () => {
    expect(missingSessionsOf(loadJson(join(RUNS, E2, 'campaign-summary.json')))).toBe(0);
    expect(missingSessionsOf(loadJson(join(RUNS, E3, 'campaign-summary.json')))).toBe(2);
  });
});
